def f(g):
    from collections import Counter
    rows_full=[i for i,r in enumerate(g) if len(set(r))==1]
    cols_full=set(j for j in range(len(g[0])) if len({g[i][j] for i in range(len(g))})==1)
    cnt=Counter()
    for i in range(len(g)):
        if i in set(rows_full): continue
        for j in range(len(g[0])):
            if j in cols_full: continue
            cnt[g[i][j]]+=1
    bg=max(cnt.items(), key=lambda kv:(kv[1],-kv[0]))[0] if cnt else 0
    H=[i for i in rows_full if g[i][0]!=bg]
    V=[j for j in cols_full if g[0][j]!=bg]
    o=[[0]*(2*len(V)+1) for _ in range(2*len(H)+1)]
